void MenuPerturbDuration::OnOpen(Menu *cto, MenuSystem *c)
{
    bool memlocked=mem_malloc_locked();
    mem_lock_malloc(false);

    ClearMenu();

    for (u_int mecount = 0; mecount < 6; ++mecount)
    {
        MenuEntryFloatEdit *pmefe = NEW MenuEntryFloatEdit(
            WAVE_PerturbStageName[mecount + 1],
            WAVE_PerturbArray[WAVE_DebugPerturbType]->duration + mecount + 1,
            0.f, 20.f, 0.1f
            );
        AddEntry(pmefe);
    }

    c->Refresh();

    Menu::OnOpen(cto, c);

    mem_lock_malloc(memlocked);
}
